import{_ as e,o as t,c as s,a4 as i}from"./chunks/framework.BUqnS5H7.js";const k=JSON.parse('{"title":"数据保留","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/02-core/chapter-07-data-retention.md","filePath":"kafka/02-core/chapter-07-data-retention.md"}'),n={name:"kafka/02-core/chapter-07-data-retention.md"};function r(o,a,l,d,c,p){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="数据保留" tabindex="-1" data-src-line="1" data-src-file="kafka/02-core/chapter-07-data-retention.md">数据保留 <a class="header-anchor" href="#数据保留" aria-label="Permalink to &quot;数据保留&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/02-core/chapter-07-data-retention.md"><p data-src-line="3" data-src-file="kafka/02-core/chapter-07-data-retention.md">Kafka 的消息不会因为被消费就删除。它一直在那里，直到保留策略把它清理掉。这个设计让 Kafka 支持&quot;回溯消费&quot;——消费者可以随时重置 Offset 重新读取历史数据。但&quot;一直存着&quot;显然不现实，磁盘终究会满。所以 Kafka 需要一套策略来决定&quot;什么时候删、怎么删&quot;。</p></blockquote><h2 id="_1-为什么消费不删除消息" tabindex="-1" data-src-line="5" data-src-file="kafka/02-core/chapter-07-data-retention.md">1. 为什么消费不删除消息 <a class="header-anchor" href="#_1-为什么消费不删除消息" aria-label="Permalink to &quot;1. 为什么消费不删除消息&quot;">​</a></h2><p data-src-line="7" data-src-file="kafka/02-core/chapter-07-data-retention.md">传统消息队列（如 RabbitMQ）的模型是：消费者确认（ACK）后，消息从队列中移除。这在&quot;一对一&quot;消费场景下没问题。</p><p data-src-line="9" data-src-file="kafka/02-core/chapter-07-data-retention.md">但 Kafka 支持多个消费者组独立消费同一个 Topic。Group A 消费了消息，Group B 还没消费——如果 Group A 消费完就删，Group B 就读不到了。</p><p data-src-line="11" data-src-file="kafka/02-core/chapter-07-data-retention.md">所以 Kafka 的设计是：<strong>消息的生命周期由保留策略决定，与消费无关</strong>。消费只影响 Offset 的推进，不影响消息的存储。</p><h2 id="_2-删除策略" tabindex="-1" data-src-line="13" data-src-file="kafka/02-core/chapter-07-data-retention.md">2. 删除策略 <a class="header-anchor" href="#_2-删除策略" aria-label="Permalink to &quot;2. 删除策略&quot;">​</a></h2><p data-src-line="15" data-src-file="kafka/02-core/chapter-07-data-retention.md">Kafka 删除的最小单位是<strong>日志段（Segment）</strong>，不是单条消息。一个 Partition 的日志由多个 Segment 文件组成，每个 Segment 有一个时间戳范围和大小。当整个 Segment 超过保留阈值时，整个文件被删除。</p><h3 id="按时间保留" tabindex="-1" data-src-line="17" data-src-file="kafka/02-core/chapter-07-data-retention.md">按时间保留 <a class="header-anchor" href="#按时间保留" aria-label="Permalink to &quot;按时间保留&quot;">​</a></h3><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">log.retention.hours</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=168    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 保留 7 天（默认）</span></span></code></pre></div><p data-src-line="23" data-src-file="kafka/02-core/chapter-07-data-retention.md">Broker 定期检查每个 Segment 的最大时间戳。如果当前时间 - Segment 最大时间戳 &gt; <code>log.retention.hours</code>，删除整个 Segment。</p><h3 id="按大小保留" tabindex="-1" data-src-line="25" data-src-file="kafka/02-core/chapter-07-data-retention.md">按大小保留 <a class="header-anchor" href="#按大小保留" aria-label="Permalink to &quot;按大小保留&quot;">​</a></h3><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">log.retention.bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=-1     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 不限制（默认）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">log.retention.bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1073741824  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 每个分区最多保留 1GB</span></span></code></pre></div><p data-src-line="32" data-src-file="kafka/02-core/chapter-07-data-retention.md">注意是<strong>每个分区</strong>的限制，不是整个 Topic。Topic 有 10 个分区，每个分区保留 1GB，总保留 10GB。</p><h3 id="为什么删除的是-segment-而不是单条消息" tabindex="-1" data-src-line="34" data-src-file="kafka/02-core/chapter-07-data-retention.md">为什么删除的是 Segment 而不是单条消息 <a class="header-anchor" href="#为什么删除的是-segment-而不是单条消息" aria-label="Permalink to &quot;为什么删除的是 Segment 而不是单条消息&quot;">​</a></h3><p data-src-line="36" data-src-file="kafka/02-core/chapter-07-data-retention.md">如果要删除单条消息，你需要在文件中找到这条消息的位置，把它标记为已删除或重写文件。这在追加日志的存储模型下代价极高——你不能原地修改文件（追加日志的&quot;不可变&quot;原则）。</p><p data-src-line="38" data-src-file="kafka/02-core/chapter-07-data-retention.md">分段后，删除变成了&quot;删文件&quot;——零拷贝开销，操作系统直接回收磁盘空间。代价是删除粒度较粗：默认 1GB 一个 Segment，即使只有一条消息过期，也要等整个 Segment 过期才能删。</p><h2 id="_3-压缩策略-保留每个-key-的最新值" tabindex="-1" data-src-line="40" data-src-file="kafka/02-core/chapter-07-data-retention.md">3. 压缩策略：保留每个 Key 的最新值 <a class="header-anchor" href="#_3-压缩策略-保留每个-key-的最新值" aria-label="Permalink to &quot;3. 压缩策略：保留每个 Key 的最新值&quot;">​</a></h2><p data-src-line="42" data-src-file="kafka/02-core/chapter-07-data-retention.md">删除策略是&quot;按时间/大小删&quot;，适用于日志收集、事件驱动等场景。但有些场景需要保留每个实体的最新状态：</p><ul data-src-line="44" data-src-file="kafka/02-core/chapter-07-data-retention.md"><li data-src-line="44" data-src-file="kafka/02-core/chapter-07-data-retention.md">数据库 CDC（变更数据捕获）：每个 Key 的最新行</li><li data-src-line="45" data-src-file="kafka/02-core/chapter-07-data-retention.md">配置中心：每个配置项的最新值</li><li data-src-line="46" data-src-file="kafka/02-core/chapter-07-data-retention.md">用户 Session：每个 Session 的最新数据</li></ul><p data-src-line="48" data-src-file="kafka/02-core/chapter-07-data-retention.md">压缩策略（<code>log.cleanup.policy=compact</code>）保留每个 Key 的最新值，删除旧版本：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>压缩前：                      压缩后：</span></span>
<span class="line"><span>Key1: Value1 (offset 0)       Key1: Value3 (offset 4)  ← 最新</span></span>
<span class="line"><span>Key2: Value1 (offset 1)       Key2: Value2 (offset 3)  ← 最新</span></span>
<span class="line"><span>Key1: Value2 (offset 2)       Key3: Value1 (offset 5)  ← 唯一</span></span>
<span class="line"><span>Key2: Value2 (offset 3)</span></span>
<span class="line"><span>Key1: Value3 (offset 4)</span></span>
<span class="line"><span>Key3: Value1 (offset 5)</span></span></code></pre></div><p data-src-line="60" data-src-file="kafka/02-core/chapter-07-data-retention.md">压缩后的 Topic 像一个持久化的 HashMap——每个 Key 只保留最新的一条消息。</p><h3 id="墓碑消息-tombstone" tabindex="-1" data-src-line="62" data-src-file="kafka/02-core/chapter-07-data-retention.md">墓碑消息（Tombstone） <a class="header-anchor" href="#墓碑消息-tombstone" aria-label="Permalink to &quot;墓碑消息（Tombstone）&quot;">​</a></h3><p data-src-line="64" data-src-file="kafka/02-core/chapter-07-data-retention.md">怎么删除一个 Key？发送一条 Value 为 <code>null</code> 的消息：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">producer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ProducerRecord&lt;&gt;(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;topic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, key, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><p data-src-line="70" data-src-file="kafka/02-core/chapter-07-data-retention.md">这条 null-value 消息就是&quot;墓碑&quot;。压缩过程中，它会删除该 Key 的所有旧版本。墓碑消息本身保留 <code>log.cleaner.delete.retention.ms</code>（默认 24 小时）后被清理。</p><h2 id="_4-混合策略" tabindex="-1" data-src-line="72" data-src-file="kafka/02-core/chapter-07-data-retention.md">4. 混合策略 <a class="header-anchor" href="#_4-混合策略" aria-label="Permalink to &quot;4. 混合策略&quot;">​</a></h2><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">log.cleanup.policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=delete,compact</span></span></code></pre></div><p data-src-line="78" data-src-file="kafka/02-core/chapter-07-data-retention.md">先压缩（保留每个 Key 的最新值），再按时间删除旧数据。适用于需要&quot;保留最新状态，但也不要无限增长&quot;的场景，如事件溯源。</p><h2 id="_5-磁盘容量规划" tabindex="-1" data-src-line="80" data-src-file="kafka/02-core/chapter-07-data-retention.md">5. 磁盘容量规划 <a class="header-anchor" href="#_5-磁盘容量规划" aria-label="Permalink to &quot;5. 磁盘容量规划&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>磁盘容量 = 每日消息量 × 消息大小 × 保留天数 × 副本因子 × 1.2（余量）</span></span></code></pre></div><p data-src-line="86" data-src-file="kafka/02-core/chapter-07-data-retention.md">示例：每日 1 亿条消息，每条 1KB，保留 7 天，3 副本：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1亿 × 1KB × 7 × 3 × 1.2 = 2.52 TB</span></span></code></pre></div><p data-src-line="92" data-src-file="kafka/02-core/chapter-07-data-retention.md">磁盘空间不足的排查见 <a href="./../05-troubleshooting/chapter-05-disk-space.html">磁盘空间不足</a>。</p>`,35)])])}const f=e(n,[["render",r]]);export{k as __pageData,f as default};
